CREATE TABLE IF NOT EXISTS ev(day TEXT NOT NULL,hr INTEGER NOT NULL,t TEXT NOT NULL,src TEXT NOT NULL,dev TEXT NOT NULL,n INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,hr,t,src,dev));
CREATE TABLE IF NOT EXISTS vis(day TEXT NOT NULL,sid TEXT NOT NULL,PRIMARY KEY(day,sid));
CREATE TABLE IF NOT EXISTS stage(day TEXT NOT NULL,sid TEXT NOT NULL,t TEXT NOT NULL,PRIMARY KEY(day,sid,t));
CREATE TABLE IF NOT EXISTS log(id INTEGER PRIMARY KEY AUTOINCREMENT,ts INTEGER NOT NULL,t TEXT NOT NULL,src TEXT NOT NULL,dev TEXT NOT NULL);
